/**
 * Stable identity of an expression across re-seeds: lowercased, diacritics
 * folded away, punctuation collapsed — so « Pognon » and « pognon » collide
 * while « 拴Q » and « 栓Q » stay distinct.
 */
export function slangSlug(language: string, expression: string): string {
  // Fold a trailing parenthetical transliteration (« 牛逼 (niúbī) » ≡ « 牛逼 »)
  // before slugging, so suffixed and bare spellings share one identity.
  const base = expression
    .replace(/\s*\([^()]*\)\s*$/, "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^\p{L}\p{N}]+/gu, " ")
    .trim();
  return `${language}:${base}`;
}

